const es = self.nearbyEnemies();
const pri = {knight:0, turret:1, agent:2, nexus:3, worker:4, wall:5};
let best=null, bs=1e9;
for (const e of es){ const d=self.distanceTo(e); if(d<=self.range){ const s=(pri[e.type]??6)*1000+e.hp; if(s<bs){bs=s;best=e;} } }
if (best){ self.attack(best); return; }
const eb = self.enemyBase();
if(!m.mode) m.mode='rally';
const allies = self.nearbyAllies().filter(a=>a.type==='knight');
const RX=8, RY=8, GROUP=6;
if(m.mode==='rally'){
  const e=self.nearestEnemy();
  if(e && e.type!=='wall' && self.distanceTo(e)<=4){ self.moveTo(e.x,e.y); return; }
  if(self.distanceToPos(RX,RY)>1){ self.moveTo(RX,RY); return; }
  if(allies.length>=GROUP-1){ m.mode='attack'; } else { self.hold(); return; }
}
if(m.mode==='attack'){
  if(allies.length===0 && self.hp<40){ m.mode='rally'; self.moveTo(RX,RY); return; }
  const e=self.nearestEnemy();
  if(e && e.type!=='wall' && e.type!=='agent' && self.distanceTo(e)<=3){ self.moveTo(e.x,e.y); return; }
  const nx=es.find(x=>x.type==='nexus'); if(nx){ self.moveTo(nx.x,nx.y); return; }
  const ag=es.find(x=>x.type==='agent'); if(ag){ self.moveTo(ag.x,ag.y); return; }
  const tr=es.find(x=>x.type==='turret'); if(tr){ self.moveTo(tr.x,tr.y); return; }
  if(eb) self.moveTo(eb.x, eb.y); else self.hold();
}

